    private void sendDownload(){if(WallpaperUploadPanel.lanAddress(ui)==null){error="未连接局域网，请连接 Wi-Fi 或网线";render();return;}if(receipt!=null)download();else copyToReceived("download");}
    private void download(){if(receipt==null)return;if(server==null){startSession(this::download);return;}try{server.offer(receipt.id);go("download","file-return-detail");}catch(IOException failure){error="文件不存在或已移除，请重新读取";render();}}
    private void install(){if(receipt!=null){launchInstall(receipt.id,null,null);return;}if(selected==null||busy)return;FileTransferSource.Item item=selected;busy=true;render();int version=++jobVersion;worker.execute(()->{File temp=null;try{File cache=new File(ui.getCacheDir(),"selected-apks");if(!cache.isDirectory()&&!cache.mkdirs())throw new IOException("安装准备目录不可用");temp=File.createTempFile("selected-apk-",".apk",cache);try(InputStream in=input(item);FileOutputStream output=new FileOutputStream(temp)){FileTransferPolicy.copy(in,output,item.bytes,Math.min(FileTransferPolicy.MAX_FILE,ui.getCacheDir().getUsableSpace()-FileTransferPolicy.RESERVE),()->!destroyed&&version==jobVersion,(a,b)->{});output.getFD().sync();}File ready=temp;main.post(()->{if(!open()||version!=jobVersion){if(!ready.delete())DiagnosticLog.info("file_tools.install_source_retained","cancelled");return;}busy=false;installSource=ready;launchInstall(UUID.randomUUID().toString(),ready,item.name);});}catch(IOException|RuntimeException failure){if(temp!=null&&!temp.delete())DiagnosticLog.info("file_tools.install_source_retained","failed");main.post(()->{if(open()&&version==jobVersion){busy=false;error="安装文件准备失败，请检查文件和存储空间";render();}});}});}
    private void launchInstall(String id,File input,String name){Intent intent=new Intent(ui,ApkInstallActivity.class).putExtra("file",id).putExtra("begin-install",true);if(!SettingsFocusMotion.reduced())try{int width=ui.getResources().getDisplayMetrics().widthPixels,height=ui.getResources().getDisplayMetrics().heightPixels;Bitmap backdrop=Bitmap.createBitmap(320,Math.max(1,Math.round(320f*height/width)),Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(backdrop);canvas.scale(320f/width,320f/width);ui.drawSheetBackdrop(canvas);intent.putExtra("backdrop",backdrop);}catch(OutOfMemoryError unavailable){DiagnosticLog.info("file_tools.backdrop_unavailable","memory");}if(input!=null)intent.putExtra("source-file",input.getAbsolutePath()).putExtra("source-name",name);external=true;sheet.dialog.hide();try{ui.startActivityForResult(intent,INSTALL);}catch(ActivityNotFoundException|SecurityException failure){external=false;sheet.dialog.show();error="系统安装入口不可用，请通过电脑安装";render();}}
    private void preparePreview(){
        if(busy)return;discard();busy=true;error="";int version=++jobVersion;FileTransferStore.Entry selectedReceipt=receipt;FileTransferSource.Item item=selected;phase="preview";render();worker.execute(()->{WallpaperImport.Prepared ready=null;Bitmap image=null;WallpaperCatalog.Entry existing=null;try{String known=selectedReceipt==null?"":ui.getSharedPreferences("file-transfer-wallpapers",0).getString(selectedReceipt.id,"");existing=WallpaperStore.get(ui).snapshot().find(known);if(existing==null){try(InputStream in=selectedReceipt!=null?new FileInputStream(store.file(selectedReceipt.id)):input(item)){ready=WallpaperImport.prepare(ui,in,selectedReceipt!=null?selectedReceipt.bytes:item.bytes,selectedReceipt!=null?selectedReceipt.name:item.name,WallpaperImport.video(selectedReceipt!=null?selectedReceipt.name:item.name,null),()->!destroyed&&version==jobVersion,"source=file_tools_preview");}}if(ready!=null&&ready.video==null){BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(ready.width/options.inSampleSize>1280||ready.height/options.inSampleSize>720)options.inSampleSize*=2;image=BitmapFactory.decodeFile(ready.existing().getPath(),options);if(image==null)throw new IOException("图片无法读取");}else if(existing!=null&&!existing.video())image=WallpaperImages.decode(ui,WallpaperStore.get(ui),existing,1280,720);WallpaperImport.Prepared draft=ready;Bitmap picture=image;WallpaperCatalog.Entry catalogEntry=existing;main.post(()->{if(!open()||version!=jobVersion){if(draft!=null)draft.discard();return;}prepared=draft;photo=picture;mediaEntry=catalogEntry!=null?catalogEntry:entry(draft);busy=false;focus="file-preview";render();});}catch(IOException|RuntimeException|OutOfMemoryError failure){if(ready!=null)ready.discard();main.post(()->{if(open()&&version==jobVersion){busy=false;error="文件无法预览，请检查格式、授权或存储空间";phase="detail";render();}});}});
    }
    private WallpaperCatalog.Entry entry(WallpaperImport.Prepared draft){WallpaperVideo.Info info=draft.video;return info==null?new WallpaperCatalog.Entry(draft.id,draft.name,draft.width,draft.height,(draft.existing()==null?0:draft.existing().length())):new WallpaperCatalog.Entry(draft.id,draft.name,draft.width,draft.height,(draft.existing()==null?0:draft.existing().length()),"video",info.mime,info.durationMs,info.fps,info.rotation,info.pixelRatio);}
    private void previewBody(){if(mediaEntry==null)return;stopPreview();FrameLayout frame=new SurfaceCorners.Frame(ui);frame.setBackgroundDrawable(ui.surface(Color.BLACK,Color.BLACK,0,9.6f));UiCompat.clipOutline(frame);LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,ui.px(182.4f));fp.topMargin=0;fp.bottomMargin=ui.px(3.84f);sheet.body.addView(frame,fp);if(!mediaEntry.video()){ImageView image=new ImageView(ui);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setImageBitmap(photo);frame.addView(image,new FrameLayout.LayoutParams(-1,-1));return;}float aspect=VideoGeometry.aspect(mediaEntry.width,mediaEntry.height,mediaEntry.pixelRatio,mediaEntry.rotation);int maximumWidth=ui.px(500.1f),maximumHeight=ui.px(182.4f),width=Math.min(maximumWidth,Math.round(maximumHeight*aspect)),height=Math.min(maximumHeight,Math.round(maximumWidth/aspect));previewHost=new FrameLayout(ui);frame.addView(previewHost,new FrameLayout.LayoutParams(width,height,Gravity.CENTER));video=new VideoWallpaperPlayer(ui,previewHost,true);video.setSound(false);File file=prepared==null?null:prepared.existing();video.play(mediaEntry,file,new VideoWallpaperPlayer.Listener(){public void ready(){}public void stopped(){}public void failed(VideoWallpaperPlayer.Failure reason){if(open()&&phase.equals("preview")){error=reason.hint(true);mediaEntry=null;render();}}});}
    private void stopPreview(){if(video!=null){video.destroy();video=null;}previewHost=null;}
    private void discard(){stopPreview();WallpaperImport.Prepared value=prepared;prepared=null;mediaEntry=null;photo=null;if(value!=null)value.discard();}
    private void applyWallpaper(){
        if(busy||mediaEntry==null)return;stopPreview();busy=applying=true;int version=++jobVersion;
        WallpaperImport.Prepared draft=prepared;WallpaperCatalog.Entry chosen=mediaEntry;String receiptId=receipt==null?null:receipt.id,title=name();render();
        worker.execute(()->{try{
            WallpaperCatalog.Entry saved=draft==null?chosen:draft.save(title,()->!destroyed&&version==jobVersion);
            main.post(()->{if(!open()||version!=jobVersion||!active)return;try{
                WallpaperStore.get(ui).select(saved.id);
                if(receiptId!=null)ui.getSharedPreferences("file-transfer-wallpapers",0).edit().putString(receiptId,saved.id).apply();
                busy=applying=false;PhoneSettingsSession.get(ui).configurationChanged();ui.feedback("文件已导入并设为壁纸");close();
            }catch(IOException failure){busy=applying=false;error="壁纸保存失败，文件和预览已保留";render();}});
        }catch(IOException|RuntimeException failure){main.post(()->{if(open()&&version==jobVersion){busy=applying=false;error="壁纸保存失败，文件和预览已保留";render();}});}});
    }
    void activityResult(int request,int result,Intent data){
        if(request!=PICK&&request!=TREE&&request!=INSTALL)return;if(!open())return;external=false;sheet.dialog.show();if(request==INSTALL){if(installSource!=null){if(installSource.isFile()&&!installSource.delete())DiagnosticLog.info("file_tools.install_source_retained","installer_return");installSource=null;}phase="install";installerOpened=data!=null&&data.getBooleanExtra("installer-opened",false);error="";render();return;}
        if(result!=android.app.Activity.RESULT_OK||data==null||data.getData()==null){error="未选择文件或目录，可继续浏览存储或使用局域网传输";render();return;}Uri uri=data.getData();if(request==TREE){if(!FileTransferSource.Documents.validTree(uri)){error="目录授权无效，请重新选择";render();return;}source=treeSource;tree=uri;current=FileTransferSource.Documents.root(uri);folder=boundary=null;parents.clear();temporaryDirectory=false;try{FileTransferSource.Documents.remember(ui,source==2,uri,data.getFlags());}catch(IOException failure){temporaryDirectory=true;error=failure.getMessage();}phase="list";focus="file-options";readList();}
        else{int version=++jobVersion;worker.execute(()->{try{FileTransferSource.Item item=FileTransferSource.selected(ui,uri);main.post(()->{if(open()&&version==jobVersion){receipt=null;selected=item;source=1;go("detail",FileTransferPolicy.apk(item.name)?"file-install":"file-preview");}});}catch(IOException|RuntimeException failure){main.post(()->{if(open()&&version==jobVersion){error="选中文件无法读取，请重新选择或检查授权";render();}});}});}
    }
    void permissionResult(int request){if(request==PERMISSION&&open()){go("list","file-options");readList();}}
    private String phoneFilesKey="";
    private final Runnable phoneChanged=this::phoneChanged;
    private void phoneChanged(){String[] names=new File(ui.getFilesDir(),"received-files").list();if(names==null)return;java.util.Arrays.sort(names);String key=java.util.Arrays.toString(names);if(key.equals(phoneFilesKey))return;phoneFilesKey=key;if(open()&&active&&!busy&&phase.equals("list"))readList();}
    void resume(){active=true;PhoneSettingsSession.get(ui).observeConfiguration(phoneChanged);retaining=false;if(open()&&!external){sheet.dialog.show();if(phase.equals("list"))readList();else if(phase.equals("preview")){if((mediaEntry==null||!mediaEntry.video()&&photo==null)&&!busy)preparePreview();else render();}else render();}}
    void pause(){active=false;PhoneSettingsSession.get(ui).forgetConfiguration(phoneChanged);++jobVersion;busy=applying=false;boolean had=server!=null||starting||receiving;stopSession();stopPreview();if(had&&(phase.equals("receiving")||phase.equals("download"))){phase="expired";focus="file-restart";}}
    void save(Bundle state){if(!open())return;retaining=true;remember();Bundle value=new Bundle();value.putString("phase",phase.equals("receiving")||phase.equals("download")?"expired":phase);value.putInt("source",source);value.putInt("tree-source",treeSource);value.putBoolean("installer-opened",installerOpened);value.putString("focus",phase.equals("receiving")||phase.equals("download")||phase.equals("expired")?"file-restart":focus);value.putString("error",error);value.putBoolean("external",external);value.putBoolean("temporary-directory",temporaryDirectory);if(folder!=null)value.putString("folder",folder.getAbsolutePath());if(boundary!=null)value.putString("boundary",boundary.getAbsolutePath());if(tree!=null){value.putString("tree",tree.toString());value.putString("current",current.toString());ArrayList<String> links=new ArrayList<>();for(Uri uri:parents)links.add(uri.toString());value.putStringArrayList("parents",links);}if(receipt!=null)value.putString("receipt",receipt.id);if(selected!=null){value.putString("selected-uri",selected.uri.toString());value.putString("selected-name",selected.name);value.putLong("selected-bytes",selected.bytes);if(selected.file!=null)value.putString("selected-file",selected.file.getAbsolutePath());}if(prepared!=null)prepared.saveState(value);if(installSource!=null)value.putString("install-source",installSource.getAbsolutePath());state.putBundle("file-tools",value);}
    void restore(Bundle state){Bundle value=state==null?null:state.getBundle("file-tools");if(value==null)return;phase=value.getString("phase","list");source=value.getInt("source");treeSource=value.getInt("tree-source",1);installerOpened=value.getBoolean("installer-opened");focus=phase.equals("expired")?"file-restart":value.getString("focus","file-start");error=value.getString("error","");external=value.getBoolean("external");temporaryDirectory=value.getBoolean("temporary-directory");String path=value.getString("folder"),edge=value.getString("boundary");if(path!=null)folder=new File(path);if(edge!=null)boundary=new File(edge);if(value.containsKey("tree")){tree=Uri.parse(value.getString("tree"));current=Uri.parse(value.getString("current"));ArrayList<String> links=value.getStringArrayList("parents");if(links!=null)for(String uri:links)parents.addLast(Uri.parse(uri));}try{store=new FileTransferStore(new File(ui.getFilesDir(),"received-files"));if(value.containsKey("receipt"))receipt=store.entry(value.getString("receipt"));if(value.containsKey("selected-uri"))selected=new FileTransferSource.Item(value.getString("selected-name"),value.getLong("selected-bytes"),false,Uri.parse(value.getString("selected-uri")),value.containsKey("selected-file")?new File(value.getString("selected-file")):null);if(value.containsKey("draft-id")){prepared=WallpaperImport.Prepared.restore(ui,value);mediaEntry=entry(prepared);}}catch(IOException|RuntimeException failure){phase="list";error="原文件或预览已不可用，请重新选择";}if(value.containsKey("install-source"))installSource=new File(value.getString("install-source"));create();if(phase.equals("preview")&&prepared!=null&&prepared.video==null){busy=true;WallpaperImport.Prepared draft=prepared;int version=++jobVersion;render();worker.execute(()->{BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(draft.width/options.inSampleSize>1280||draft.height/options.inSampleSize>720)options.inSampleSize*=2;Bitmap image=BitmapFactory.decodeFile(draft.existing().getPath(),options);main.post(()->{if(!open()||version!=jobVersion)return;busy=false;photo=image;if(image==null){error="原预览无法读取，请返回后重试";mediaEntry=null;phase="detail";}render();});});}if(external)sheet.dialog.hide();}
    void close(){if(applying)return;if(sheet!=null)sheet.dialog.dismiss();}
    void destroy(){PhoneSettingsSession.get(ui).forgetConfiguration(phoneChanged);destroyed=true;if(sheet!=null){sheet.dialog.setOnDismissListener(null);sheet.dialog.dismiss();sheet=null;}++jobVersion;++listVersion;stopSession();stopPreview();if(!retaining)discard();ui.unregisterReceiver(screen);main.removeCallbacksAndMessages(null);worker.shutdown();}
